'use strict';
// Generate src/renderer/tokens.css from the VW-APP-UX token set
// (config/app/tokens.json at the repo root). The CSS is committed so the
// packaged app never reads outside app/; test/tokens.test.js fails when the
// two drift. Usage: npm run tokens   (or: node scripts/gen-tokens.js --check)

const fs = require('node:fs');
const path = require('node:path');

const SRC = path.join(__dirname, '..', '..', 'config', 'app', 'tokens.json');
const OUT = path.join(__dirname, '..', 'src', 'renderer', 'tokens.css');

function render(doc) {
  const lines = [
    '/* GENERATED by app/scripts/gen-tokens.js from config/app/tokens.json',
    '   (VW-APP-UX, version ' + doc.version + '). Do not edit by hand. */',
    ':root {',
  ];
  for (const [name, hex] of Object.entries(doc.colors)) {
    lines.push('  --vw-' + name.replace(/\./g, '-') + ': ' + hex + ';');
  }
  lines.push('  --vw-plate-alpha: ' + doc.plate_alpha + ';');
  lines.push('}');
  return lines.join('\n') + '\n';
}

function expected() {
  return render(JSON.parse(fs.readFileSync(SRC, 'utf8')));
}

if (require.main === module) {
  const want = expected();
  if (process.argv.includes('--check')) {
    const have = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
    if (have !== want) {
      process.stderr.write('tokens.css is stale: run npm run tokens\n');
      process.exit(1);
    }
  } else {
    fs.writeFileSync(OUT, want, 'utf8');
  }
}

module.exports = { render, expected, SRC, OUT };
